function spell(id, title, level, school, castingTime, range, components, duration, tags, description, options = {}) {
  return {
    id,
    title,
    level,
    school,
    castingTime,
    range,
    components,
    duration,
    tags,
    source: options.source || 'TU',
    classes: options.classes || [],
    description,
    sections: options.sections || [],
    table: options.table || null
  }
}

